{
  "title": "The Gilded Cage Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "Crumbling stone gates flanked by faded royal banners, with broken statues and overgrown ivy.",
      "characters": ["Elena", "Kael", "Mira"]
    },
    {
      "scene_number": 2,
      "caption": "They slip past a cursed tower that whispers temptations.",
      "visual_description": "A spiraling black tower with glowing runes, shadows writhing at its base, and a faint lure of treasure inside.",
      "characters": ["Elena", "Kael", "Mira"]
    },
    {
      "scene_number": 3,
      "caption": "Frightened townspeople warn them of armored patrols.",
      "visual_description": "Huddled figures in torn clothes point toward a distant street where steel-clad guards march in lockstep.",
      "characters": ["Elena", "Kael", "Mira", "Townsfolk"]
    },
    {
      "scene_number": 4,
      "caption": "The party hides as a patrol passes under a broken arch.",
      "visual_description": "Sunlight glints off polished helms and spears as six guards march beneath a cracked stone archway.",
      "characters": ["Elena", "Kael", "Mira", "Armored Patrol"]
    },
    {
      "scene_number": 5,
      "caption": "They find a magic door that only opens for a true name.",
      "visual_description": "A door of pale wood covered in shifting silver letters, humming with low energy.",
      "characters": ["Elena", "Kael", "Mira"]
    },
    {
      "scene_number": 6,
      "caption": "Kael recalls the name from an old legend.",
      "visual_description": "Kael closes his eyes, hand on the door, while Elena and Mira watch anxiously.",
      "characters": ["Elena", "Kael", "Mira"]
    },
    {
      "scene_number": 7,
      "caption": "The door swings open to a dusty courtyard.",
      "visual_description": "A wide space with cracked flagstones, a dry fountain, and more tattered banners overhead.",
      "characters": ["Elena", "Kael", "Mira"]
    },
    {
      "scene_number": 8,
      "caption": "A dragon's roar echoes from a distant hill.",
      "visual_description": "The silhouette of a massive winged creature passes across the setting sun, sending birds fleeing.",
      "characters": ["Elena", "Kael", "Mira"]
    },
    {
      "scene_number": 9,
      "caption": "They enter the castle keep through a side passage.",
      "visual_description": "Narrow, dark corridor lit by flickering torches, with cobwebs and old armor stands.",
      "characters": ["Elena", "Kael", "Mira"]
    },
    {
      "scene_number": 10,
      "caption": "The throne room holds the captive princess.",
      "visual_description": "A grand but decayed hall, stained glass windows casting colored light, the princess bound to a stone throne.",
      "characters": ["Elena", "Kael", "Mira", "Princess Lyra"]
    },
    {
      "scene_number": 11,
      "caption": "Guards rush in as they free the princess.",
      "visual_description": "Heavy doors burst open, and a squad of armored soldiers charges in with drawn swords.",
      "characters": ["Elena", "Kael", "Mira", "Princess Lyra", "Armored Patrol"]
    },
    {
      "scene_number": 12,
      "caption": "Elena casts a blinding flash to cover their escape.",
      "visual_description": "A brilliant white light erupts from Elena's hands, forcing guards to shield their eyes.",
      "characters": ["Elena", "Kael", "Mira", "Princess Lyra", "Armored Patrol"]
    },
    {
      "scene_number": 13,
      "caption": "They dash through a cursed tower's base room.",
      "visual_description": "A circular chamber with illusory gold and gems on pedestals, the air thick with enchantment.",
      "characters": ["Elena", "Kael", "Mira", "Princess Lyra"]
    },
    {
      "scene_number": 14,
      "caption": "Mira disarms a magical trap on the stairs.",
      "visual_description": "A staircase lined with glowing pressure plates; Mira kneels to disable a rune while others watch.",
      "characters": ["Elena", "Kael", "Mira", "Princess Lyra"]
    },
    {
      "scene_number": 15,
      "caption": "The patrol corners them at the city wall.",
      "visual_description": "A dead-end at the base of the wall, guards closing in from both sides.",
      "characters": ["Elena", "Kael", "Mira", "Princess Lyra", "Armored Patrol"]
    },
    {
      "scene_number": 16,
      "caption": "Kael opens a hidden door with a king's seal.",
      "visual_description": "He presses an emblem on the wall, and a section of masonry slides back to reveal a tunnel.",
      "characters": ["Elena", "Kael", "Mira", "Princess Lyra"]
    },
    {
      "scene_number": 17,
      "caption": "They emerge onto the escape bridge.",
      "visual_description": "A narrow stone bridge spanning a deep gorge, mist rising from below, the city behind them.",
      "characters": ["Elena", "Kael", "Mira", "Princess Lyra"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them as they cross.",
      "visual_description": "Massive stones plunge into the chasm as the party reaches the far side, safe at last.",
      "characters": ["Elena", "Kael", "Mira", "Princess Lyra"]
    }
  ]
}

